"""
    Formula:
    Number of times term w appears in a document) / (Total number of terms in the document).
    """
def tf_score(word: Any, sentence: Any) -> object {
    word_frequency_in_sentence = 0;
    len_sentence = len(sentence);
    for word_in_sentence in sentence.split() {
        if (word == word_in_sentence) {
            word_frequency_in_sentence = word_frequency_in_sentence + 1;
        }
    }
    tf = word_frequency_in_sentence / len_sentence;
    return tf;
}

"""
    This function splits a full name into a natural first name, last name
    and middle initials.
    """
def full_name_natural_split(full_name: Any) -> object {
    parts = full_name.strip().split(' ');
    first_name = "";
    if parts {
        first_name = parts.pop(0);
    }
    if ((first_name.lower() == "el") and parts) {
        first_name += " " + parts.pop(0);
    }
    last_name = "";
    if parts {
        last_name = parts.pop();
    }
    if (
        (last_name.lower() == 'i')
        or (last_name.lower() == 'ii')
        or ((last_name.lower() == 'iii') and parts)
    ) {
        last_name = parts.pop() + " " + last_name;
    }
    middle_initials = "";
    for middle_name in parts {
        if middle_name {
            middle_initials += middle_name[0];
        }
    }
    return (first_name, middle_initials, last_name);
}

"""
    Normalizes the difference between actual and predicted values.
    :param estimate:Estimated by the model.
    :param actual: Real value in data.
    :return: MRE
    """
def magnitude_relative_error(
    estimate: Any, actual: Any, balanced: Any = False
) -> object {
    if not balanced {
        denominator = actual;
    } else {
        denominator = min(estimate, actual);
    }
    if (denominator == 0) {
        denominator = 1;
    }
    mre = abs((estimate - actual)) / float(denominator);
    return mre;
}

